# Output Paths
MODEL_SAVE_PATH = os.path.join(WORKING_DIR, "best_model.pth")
SUBMISSION_PATH = os.path.join(SUBMISSION_DIR, "submission.csv")

# =============================================================================
# Hyperparameters
# =============================================================================
SEED = 42

# Data Generation
WINDOW_SIZE = 11  # Temporal context: t-5 to t+5 (11 frames)

# Training
BATCH_SIZE = 512
LEARNING_RATE = 1e-3
EPOCHS = 15
POS_WEIGHT = 72.0  # Static weight for BCE loss to handle ~1:72 class imbalance
EARLY_STOPPING_PATIENCE = 3
NUM_WORKERS = 4

